//! Every Unicode digit that is not a decimal digit, generated from
//! CPython's own `str.isdigit()`. Do not edit by hand:
//! scripts/gen_unicode_digit.py writes it.
//!
//! `str.isdigit()` is true for a decimal digit (unicode_nd.rs) and
//! for these: Numeric_Type=Digit, such as superscripts and circled
//! digits. [`py_isdigit`] is the two together.
//!
//! Unicode 15.1.0, from CPython 3.13.13.

/// The Unicode version this table was generated from.
pub const UNICODE_VERSION: &str = "15.1.0";

/// Every code point `str.isdigit()` accepts and `str.isdecimal()` does not.
pub const DIGITS_NOT_DECIMAL: [u32; 128] = [
    0x00B2, 0x00B3, 0x00B9, 0x1369, 0x136A, 0x136B, 0x136C, 0x136D, 0x136E, 0x136F, 0x1370,
    0x1371, 0x19DA, 0x2070, 0x2074, 0x2075, 0x2076, 0x2077, 0x2078, 0x2079, 0x2080, 0x2081,
    0x2082, 0x2083, 0x2084, 0x2085, 0x2086, 0x2087, 0x2088, 0x2089, 0x2460, 0x2461, 0x2462,
    0x2463, 0x2464, 0x2465, 0x2466, 0x2467, 0x2468, 0x2474, 0x2475, 0x2476, 0x2477, 0x2478,
    0x2479, 0x247A, 0x247B, 0x247C, 0x2488, 0x2489, 0x248A, 0x248B, 0x248C, 0x248D, 0x248E,
    0x248F, 0x2490, 0x24EA, 0x24F5, 0x24F6, 0x24F7, 0x24F8, 0x24F9, 0x24FA, 0x24FB, 0x24FC,
    0x24FD, 0x24FF, 0x2776, 0x2777, 0x2778, 0x2779, 0x277A, 0x277B, 0x277C, 0x277D, 0x277E,
    0x2780, 0x2781, 0x2782, 0x2783, 0x2784, 0x2785, 0x2786, 0x2787, 0x2788, 0x278A, 0x278B,
    0x278C, 0x278D, 0x278E, 0x278F, 0x2790, 0x2791, 0x2792, 0x10A40, 0x10A41, 0x10A42,
    0x10A43, 0x10E60, 0x10E61, 0x10E62, 0x10E63, 0x10E64, 0x10E65, 0x10E66, 0x10E67, 0x10E68,
    0x11052, 0x11053, 0x11054, 0x11055, 0x11056, 0x11057, 0x11058, 0x11059, 0x1105A, 0x1F100,
    0x1F101, 0x1F102, 0x1F103, 0x1F104, 0x1F105, 0x1F106, 0x1F107, 0x1F108, 0x1F109, 0x1F10A,
];

/// `c.isdigit()`, as CPython answers it for one character.
pub fn py_isdigit(c: char) -> bool {
    crate::unicode_nd::decimal_value(c).is_some()
        || DIGITS_NOT_DECIMAL.binary_search(&(c as u32)).is_ok()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn digits_that_are_not_decimal_count() {
        for c in ['0', '9', '\u{663}', '\u{b2}', '\u{2460}', '\u{2081}'] {
            assert!(py_isdigit(c), "{c:?}");
        }
        for c in ['a', '\u{bd}', '\u{2167}', ' ', '-'] {
            assert!(!py_isdigit(c), "{c:?}");
        }
    }
}
